import React from "react";


function Sidebar({
  activePage,
  setActivePage,
}) {

  const navigation = [
    {
      id: "overview",
      label: "Overview",
      icon: "⌂",
    },

    {
      id: "topology",
      label: "Topology",
      icon: "◇",
    },

    {
      id: "workers",
      label: "Workers",
      icon: "▦",
    },

    {
      id: "partitions",
      label: "Partitions",
      icon: "▤",
    },

    {
      id: "metrics",
      label: "Metrics",
      icon: "⌁",
    },
  ];


  return (

    <aside className="sidebar">

      <div className="sidebar-brand">

        <div className="brand-icon">
          SF
        </div>

        <div>

          <div className="brand-name">
            StreamForge
          </div>

          <div className="brand-subtitle">
            Stream Processor
          </div>

        </div>

      </div>


      <nav className="sidebar-nav">

        <div className="nav-section-title">
          MONITORING
        </div>


        {navigation.map((item) => (

          <button
            key={item.id}

            className={
              activePage === item.id
                ? "nav-item active"
                : "nav-item"
            }

            onClick={() =>
              setActivePage(item.id)
            }
          >

            <span className="nav-icon">
              {item.icon}
            </span>

            <span>
              {item.label}
            </span>

          </button>

        ))}

      </nav>


      <div className="sidebar-bottom">

        <div className="sidebar-system">

          <div className="sidebar-system-header">

            <span>
              System Status
            </span>

            <span className="status-dot"></span>

          </div>


          <div className="sidebar-system-status">
            Operational
          </div>


          <div className="sidebar-system-details">
            20 workers · 20 partitions
          </div>

        </div>


        <div className="sidebar-version">
          StreamForge v0.1.0
        </div>

      </div>

    </aside>

  );
}


export default Sidebar;
